(function() {
    'use strict';

    class RedMundoAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Red que Mueve el Mundo';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    briefingKey: 'round1_briefing',
                    decisions: [
                        {
                            id: 'decision1',
                            labelKey: 'r1_tapia_label',
                            hintKey: 'r1_tapia_hint',
                            options: [
                                { value: 'coordination', labelKey: 'r1_tapia_coordination' },
                                { value: 'central', labelKey: 'r1_tapia_central' },
                                { value: 'embedded', labelKey: 'r1_tapia_embedded' }
                            ]
                        },
                        {
                            id: 'decision2',
                            labelKey: 'r1_announce_label',
                            hintKey: 'r1_announce_hint',
                            options: [
                                { value: 'oneOnOne', labelKey: 'r1_announce_one' },
                                { value: 'cascade', labelKey: 'r1_announce_cascade' },
                                { value: 'townhall', labelKey: 'r1_announce_townhall' }
                            ]
                        },
                        {
                            id: 'decision3',
                            labelKey: 'r1_priority_label',
                            hintKey: 'r1_priority_hint',
                            options: [
                                { value: 'relationships', labelKey: 'r1_priority_relationships' },
                                { value: 'brokerage', labelKey: 'r1_priority_brokerage' },
                                { value: 'quickWins', labelKey: 'r1_priority_quickwins' },
                                { value: 'authority', labelKey: 'r1_priority_authority' }
                            ]
                        }
                    ]
                },
                {
                    titleKey: 'round2_title',
                    briefingKey: 'round2_briefing',
                    decisions: [
                        {
                            id: 'decision1',
                            labelKey: 'r2_aguirre_label',
                            hintKey: 'r2_aguirre_hint',
                            options: [
                                { value: 'inclusion', labelKey: 'r2_aguirre_inclusion' },
                                { value: 'negotiate', labelKey: 'r2_aguirre_negotiate' },
                                { value: 'bypass', labelKey: 'r2_aguirre_bypass' },
                                { value: 'confrontation', labelKey: 'r2_aguirre_confrontation' }
                            ]
                        },
                        {
                            id: 'decision2',
                            labelKey: 'r2_reward_label',
                            hintKey: 'r2_reward_hint',
                            options: [
                                { value: 'crossBU', labelKey: 'r2_reward_crossbu' },
                                { value: 'hybrid', labelKey: 'r2_reward_hybrid' },
                                { value: 'functional', labelKey: 'r2_reward_functional' }
                            ]
                        },
                        {
                            id: 'decision3',
                            labelKey: 'r2_safety_label',
                            hintKey: 'r2_safety_hint',
                            options: [
                                { value: 'protocols', labelKey: 'r2_safety_protocols' },
                                { value: 'skipLevel', labelKey: 'r2_safety_skip' },
                                { value: 'consultant', labelKey: 'r2_safety_consultant' }
                            ]
                        }
                    ]
                },
                {
                    titleKey: 'round3_title',
                    briefingKey: 'round3_briefing',
                    decisions: [
                        {
                            id: 'decision1',
                            labelKey: 'r3_budget_label',
                            hintKey: 'r3_budget_hint',
                            options: [
                                { value: 'matrix', labelKey: 'r3_budget_matrix' },
                                { value: 'hybrid', labelKey: 'r3_budget_hybrid' },
                                { value: 'functional', labelKey: 'r3_budget_functional' }
                            ]
                        },
                        {
                            id: 'decision2',
                            labelKey: 'r3_eval_label',
                            hintKey: 'r3_eval_hint',
                            options: [
                                { value: 'team', labelKey: 'r3_eval_team' },
                                { value: 'bu', labelKey: 'r3_eval_bu' },
                                { value: 'individual', labelKey: 'r3_eval_individual' },
                                { value: 'company', labelKey: 'r3_eval_company' }
                            ]
                        },
                        {
                            id: 'decision3',
                            labelKey: 'r3_knowledge_label',
                            hintKey: 'r3_knowledge_hint',
                            options: [
                                { value: 'crossRotation', labelKey: 'r3_knowledge_rotation' },
                                { value: 'digitalPlatform', labelKey: 'r3_knowledge_platform' },
                                { value: 'noAction', labelKey: 'r3_knowledge_none' }
                            ]
                        }
                    ]
                }
            ];

            this.EVENTS = [
                [
                    { key: 'event_scada_offer', prob: 0.30, ociDelta: -3, retentionDelta: -4, complianceDelta: 0 },
                    null
                ],
                [
                    { key: 'event_safety_survey', prob: 0.50, ociDelta: -2, retentionDelta: -3, complianceDelta: 0 },
                    { key: 'event_cne_audit', prob: 0.25, ociDelta: 0, retentionDelta: 0, complianceDelta: -8 }
                ],
                [
                    { key: 'event_merger_rumor', prob: 0.20, ociDelta: -4, retentionDelta: -5, complianceDelta: 0 },
                    { key: 'event_tapia_leaves', prob: 0.15, ociDelta: -10, retentionDelta: -3, complianceDelta: -5 }
                ]
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    oci: 45,
                    regulatoryCompliance: 40,
                    employeeRetention: 92,
                    starModelAlignment: 30,
                    influenceEffectiveness: 10,
                    tapiaRole: '',
                    aguirreStatus: 'active',
                    ociHistory: [],
                    complianceHistory: [],
                    retentionHistory: [],
                    starHistory: [],
                    influenceHistory: [],
                    activeEvents: [],
                    eventsOccurred: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decision1: '',
                    decision2: '',
                    decision3: ''
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var sel1 = document.getElementById('decision1Select');
            var sel2 = document.getElementById('decision2Select');
            var sel3 = document.getElementById('decision3Select');

            if (sel1) decisions.decision1 = sel1.value;
            if (sel2) decisions.decision2 = sel2.value;
            if (sel3) decisions.decision3 = sel3.value;

            if (!decisions.decision1 || !decisions.decision2 || !decisions.decision3) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('validation_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var ociDelta = 0;
            var compDelta = 0;
            var retDelta = 0;
            var starDelta = 0;
            var inflDelta = 0;

            if (round === 1) {
                ds.tapiaRole = d.decision1;
                if (d.decision1 === 'coordination') { ociDelta += 12; starDelta += 8; }
                else if (d.decision1 === 'central') { ociDelta += 5; starDelta += 3; }
                else if (d.decision1 === 'embedded') { ociDelta -= 8; starDelta += 2; }

                if (d.decision2 === 'oneOnOne') { inflDelta += 12; retDelta += 3; }
                else if (d.decision2 === 'cascade') { inflDelta += 5; retDelta += 1; }
                else if (d.decision2 === 'townhall') { inflDelta -= 2; retDelta -= 2; }

                if (d.decision3 === 'relationships') { inflDelta += 8; retDelta += 2; }
                else if (d.decision3 === 'brokerage') { ociDelta += 10; inflDelta += 6; }
                else if (d.decision3 === 'quickWins') { compDelta += 5; starDelta += 3; }
                else if (d.decision3 === 'authority') { compDelta += 3; inflDelta -= 5; retDelta -= 3; }
            }
            else if (round === 2) {
                if (d.decision1 === 'inclusion') { ociDelta += 8; retDelta += 5; inflDelta += 6; ds.aguirreStatus = 'neutralized'; }
                else if (d.decision1 === 'negotiate') { ociDelta += 4; retDelta += 2; inflDelta += 3; ds.aguirreStatus = 'neutralized'; }
                else if (d.decision1 === 'bypass') { ociDelta -= 3; retDelta -= 2; ds.aguirreStatus = 'active'; }
                else if (d.decision1 === 'confrontation') { ociDelta -= 10; retDelta -= 8; inflDelta -= 4; ds.aguirreStatus = 'resigned'; }

                if (d.decision2 === 'crossBU') { ociDelta += 10; starDelta += 15; compDelta += 8; }
                else if (d.decision2 === 'hybrid') { ociDelta += 5; starDelta += 8; compDelta += 4; }
                else if (d.decision2 === 'functional') { ociDelta -= 5; starDelta -= 3; compDelta -= 4; }

                if (d.decision3 === 'protocols') { retDelta += 5; ociDelta += 5; inflDelta += 3; }
                else if (d.decision3 === 'skipLevel') { retDelta += 3; inflDelta += 5; }
                else if (d.decision3 === 'consultant') { retDelta += 2; starDelta += 3; }
            }
            else if (round === 3) {
                if (d.decision1 === 'matrix') { starDelta += 12; compDelta += 10; ociDelta += 8; }
                else if (d.decision1 === 'hybrid') { starDelta += 6; compDelta += 5; ociDelta += 4; }
                else if (d.decision1 === 'functional') { starDelta -= 5; compDelta -= 6; ociDelta -= 6; }

                if (d.decision2 === 'team') { ociDelta += 6; retDelta += 3; starDelta += 5; }
                else if (d.decision2 === 'bu') { ociDelta += 4; compDelta += 4; starDelta += 4; }
                else if (d.decision2 === 'individual') { ociDelta -= 4; retDelta -= 2; }
                else if (d.decision2 === 'company') { ociDelta += 2; starDelta += 2; }

                if (d.decision3 === 'crossRotation') { ociDelta += 7; inflDelta += 4; retDelta += 2; }
                else if (d.decision3 === 'digitalPlatform') { ociDelta += 4; starDelta += 3; compDelta += 3; }
                else if (d.decision3 === 'noAction') { ociDelta -= 3; }
            }

            var activeEvents = [];
            var roundEvents = this.EVENTS[round - 1];
            if (roundEvents) {
                for (var e = 0; e < roundEvents.length; e++) {
                    var evt = roundEvents[e];
                    if (evt && Math.random() < evt.prob) {
                        ociDelta += evt.ociDelta;
                        retDelta += evt.retentionDelta;
                        compDelta += evt.complianceDelta;
                        activeEvents.push(evt.key);
                        ds.eventsOccurred.push(evt.key);
                    }
                }
            }
            ds.activeEvents = activeEvents;

            ds.oci = Math.max(0, Math.min(100, ds.oci + ociDelta));
            ds.regulatoryCompliance = Math.max(0, Math.min(100, ds.regulatoryCompliance + compDelta));
            ds.employeeRetention = Math.max(0, Math.min(100, ds.employeeRetention + retDelta));
            ds.starModelAlignment = Math.max(0, Math.min(100, ds.starModelAlignment + starDelta));
            ds.influenceEffectiveness = Math.max(0, Math.min(100, ds.influenceEffectiveness + inflDelta));

            ds.ociHistory.push(ds.oci);
            ds.complianceHistory.push(ds.regulatoryCompliance);
            ds.retentionHistory.push(ds.employeeRetention);
            ds.starHistory.push(ds.starModelAlignment);
            ds.influenceHistory.push(ds.influenceEffectiveness);

            var results = {
                period: state.currentPeriod,
                oci: ds.oci,
                ociDelta: ociDelta,
                compliance: ds.regulatoryCompliance,
                retention: ds.employeeRetention,
                starModel: ds.starModelAlignment,
                influence: ds.influenceEffectiveness,
                aguirreStatus: ds.aguirreStatus,
                events: activeEvents.length > 0 ? activeEvents.join(', ') : '-'
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
                self._showEvents(activeEvents);
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('ociDisplay', 'domainState.oci', function(v) { return Math.round(v); });
            uiManager.bind('complianceDisplay', 'domainState.regulatoryCompliance', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('retentionDisplay', 'domainState.employeeRetention', function(v) { return Math.round(v) + '%'; });
            uiManager.bind('starDisplay', 'domainState.starModelAlignment', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('influenceDisplay', 'domainState.influenceEffectiveness', function(v) { return Math.round(v) + '/100'; });
        }

        getChartConfig() {
            return {
                ociChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_oci_label'),
                                data: [],
                                borderColor: '#2980b9',
                                backgroundColor: 'rgba(41,128,185,0.15)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3
                            },
                            {
                                label: this._t('chart_compliance_label'),
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_oci_title') }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                },
                kpiChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_star_label'),
                                data: [],
                                backgroundColor: 'rgba(230,126,34,0.7)',
                                borderColor: '#e67e22',
                                borderWidth: 1
                            },
                            {
                                label: this._t('chart_influence_label'),
                                data: [],
                                backgroundColor: 'rgba(192,57,43,0.7)',
                                borderColor: '#c0392b',
                                borderWidth: 1
                            },
                            {
                                label: this._t('chart_retention_label'),
                                data: [],
                                backgroundColor: 'rgba(142,68,173,0.7)',
                                borderColor: '#8e44ad',
                                borderWidth: 1
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_kpi_title') }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.ociHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                ociChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.ociHistory },
                        { data: state.domainState.complianceHistory }
                    ]
                },
                kpiChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.starHistory },
                        { data: state.domainState.influenceHistory },
                        { data: state.domainState.retentionHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var finalOci = last.results ? last.results.oci : 45;
            var finalCompliance = last.results ? last.results.compliance : 40;
            var finalRetention = last.results ? last.results.retention : 92;
            var finalStar = last.results ? last.results.starModel : 30;
            var finalInfluence = last.results ? last.results.influence : 10;

            var score = Math.round(
                finalOci * 0.35 +
                finalCompliance * 0.25 +
                finalRetention * 0.20 +
                finalStar * 0.15 +
                finalInfluence * 0.05
            );

            var performanceKey = 'perf_needs';
            if (score >= 75) performanceKey = 'perf_excellent';
            else if (score >= 60) performanceKey = 'perf_good';
            else if (score >= 45) performanceKey = 'perf_developing';
            var performance = this._t(performanceKey);

            var insights = [];
            if (finalOci >= 60) insights.push(this._t('ins_oci_high'));
            if (finalOci < 45) insights.push(this._t('ins_oci_low'));
            if (finalCompliance >= 70) insights.push(this._t('ins_comp_high'));
            if (finalCompliance < 50) insights.push(this._t('ins_comp_low'));
            if (finalRetention >= 85) insights.push(this._t('ins_ret_high'));
            if (finalRetention < 80) insights.push(this._t('ins_ret_low'));
            if (finalStar >= 60) insights.push(this._t('ins_star_high'));
            if (finalStar < 40) insights.push(this._t('ins_star_low'));
            if (insights.length === 0) insights.push(this._t('ins_mixed'));

            return {
                overallScore: score,
                oci: finalOci,
                compliance: finalCompliance,
                retention: finalRetention,
                starModel: finalStar,
                influence: finalInfluence,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && results.ociDelta < 0) {
                return window.mySimulation.t('hint_oci_drop');
            }
            if (state.currentPeriod === 2 && state.domainState.aguirreStatus === 'resigned') {
                return window.mySimulation.t('hint_aguirre_resigned');
            }
            if (state.domainState.starModelAlignment < 35) {
                return window.mySimulation.t('hint_star_low');
            }
            if (state.domainState.employeeRetention < 80) {
                return window.mySimulation.t('hint_retention_low');
            }
            if (results.ociDelta > 10) {
                return window.mySimulation.t('hint_oci_great');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.oci', label: 'OCI', i18nKey: 'col_oci', formatter: function(v) { return Math.round(v); } },
                { key: 'results.ociDelta', label: 'OCI Change', i18nKey: 'col_oci_delta', formatter: function(v) { return (v >= 0 ? '+' : '') + Math.round(v); } },
                { key: 'results.compliance', label: 'Compliance', i18nKey: 'col_compliance', formatter: function(v) { return Math.round(v) + '/100'; } },
                { key: 'results.retention', label: 'Retention', i18nKey: 'col_retention', formatter: function(v) { return Math.round(v) + '%'; } },
                { key: 'results.starModel', label: 'Star Model', i18nKey: 'col_star', formatter: function(v) { return Math.round(v) + '/100'; } },
                { key: 'results.influence', label: 'Influence', i18nKey: 'col_influence', formatter: function(v) { return Math.round(v) + '/100'; } },
                { key: 'results.events', label: 'Events', i18nKey: 'col_events' }
            ];
        }

        getPresets() { return null; }

        _t(k) { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; }

        getTranslations() {
            return {
                en: {
                    title:                 `La Red que Mueve el Mundo`,
                    subtitle:              `Organizational Network Analysis at Energia del Sur S.A.`,
                    round_label:           `Round`,
                    period_of:             `of`,
                    oci_label:             `Connectivity Index (OCI)`,
                    compliance_label:      `Regulatory Compliance`,
                    retention_label:       `Employee Retention`,
